// the sources just downloaded, plus earlier ones still waiting for a screen
const seen = new Set(), out = [];
for (const x of [...$input.all(), ...$('Unscreened Sources').all()].map(i => i.json))
  if (x.source_id && !seen.has(String(x.source_id))) { seen.add(String(x.source_id)); out.push({ json: { source_id: x.source_id } }); }
return out;
